def rango_al_momento(apps, schema_editor):
    """Los partes ya cargados toman el rango de ese año (número de mérito) o, si no hay, el actual."""
    PartePersonal = apps.get_model("partes", "PartePersonal")
    NumeroMerito = apps.get_model("partes", "NumeroMerito")
    for fila in PartePersonal.objects.select_related("parte", "integrante"):
        numero = NumeroMerito.objects.filter(integrante=fila.integrante, anio=fila.parte.anio).first()
        fila.rango_id = numero.rango_id if numero else fila.integrante.rango_id
        fila.save(update_fields=["rango"])


